const execution = $input.first().json.execution || {};
const workflow = $input.first().json.workflow || {};
const lastNode = execution.lastNodeExecuted || 'unknown';
const error = execution.error?.message || 'Unknown error';
const mode = execution.mode || 'unknown';

return [{
  json: {
    text: `🔥 <b>Workflow Crashed</b>\n\n📋 <b>${workflow.name || 'Unknown'}</b>\n💥 Node: <code>${lastNode}</code>\n❌ ${error}\n🔄 Mode: ${mode}\n📅 ${new Date().toISOString()}`
  }
}];
